      e.channelId ?? null,
      e.opportunityId ?? null,
      e.podId ?? null,
      e.adId ?? null,
      e.campaignId ?? null,
      e.creativeId ?? null,
      e.programId ?? null,
      e.playheadPosition ?? null,
      e.deviceType ?? null,
